def find_permutation(n, k):
    if k == 0:
        if n == 1:
            return [1]
        else:
            return -1
    elif k == n:
        return list(range(n, 0, -1))
    else:
        if n % 2 == 0 and k == n // 2:
            permutation = list(range(1, n + 1))
            for i in range(0, n, 2):
                permutation[i], permutation[i + 1] = permutation[i + 1], permutation[i]
            return permutation
        else:
            return -1

